//! The M5a control-plane protobuf (generated by prost from
//! `proto/control.proto`) plus small ergonomic constructors.
//!
//! Control plane only this milestone — data-plane messages (commit-push,
//! object-fetch, shared-push, ...) are defined in their own later slices.

// prost-generated code; don't hold it to our hand-written lint bar.
#[allow(clippy::all, clippy::pedantic, clippy::nursery)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/softfig.net.control.v1.rs"));
}

pub use generated::{
    frame, ArtifactChunk, ArtifactRequest, ChainRejected, CommitData, DeviceStateAnnounce,
    EnvEntry, Frame, GetCommit, GetObject, GetTip, GetTree, HelloPayload, JobAccept, JobAttach,
    JobCancel, JobEvent, JobLog, JobOffer, JobReject, JobResult, ObjectData, Ping, Pong,
    RelayConnect, RelayData, ReplicaDone, ReplicaGrant, RunnerCaps, RunnerCert, RunnerCertRevoke,
    RunnerHandshake, ShareOffer, SharedChainPush, SharedKeyCommit, SharedKeyHandoff,
    SharedKeyReveal, SourceChunk, SourceHave, StateAnnounce, TipAnnounce, TreeData, TreeEntryMsg,
    TurnRequest, TurnRevoke, TurnYield,
};

/// Redacting `Debug` for the M5d recovery hand-off (slice 015 / LEAK-1). The
/// message carries raw `S` in `shared_key`; prost's default field-dumping
/// `Debug` is suppressed for this type in `build.rs` (`skip_debug`), so this
/// hand-written impl is the only one — it prints the framing fields but never
/// the key bytes. That makes a future `eprintln!("{frame:?}")` / panic-with-frame
/// unable to dump `S` to journald. Every enclosing type (`frame::Kind`, `Frame`,
/// `CeremonyOutcome::Handoff`) recurses through this impl for free.
impl std::fmt::Debug for SharedKeyHandoff {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SharedKeyHandoff")
            .field("chain_id", &self.chain_id)
            .field("transcript_record", &self.transcript_record)
            .field(
                "shared_key",
                &format_args!("<redacted {}B>", self.shared_key.len()),
            )
            .finish()
    }
}

